/* Storelib Payments status, cached on the creator's row: payments_status (NOT_STARTED, INCOMPLETE, VERIFYING, ACTION_REQUIRED, BANK_REQUIRED, ACTIVE, RESTRICTED, PAYOUT_FAILED or SUSPENDED, worked out from the Stripe account by lib/payments/stripe/status.ts) and last_stripe_sync_at (when the server last read the account from Stripe). Only the server writes them, after reading Stripe; Stripe stays the judge and the app re-reads it whenever the payments page opens. Private, like the other Stripe columns (part 63). Safe to run more than once. */
DO $$ BEGIN IF to_regclass('public.creators') IS NULL THEN RAISE NOTICE 'payments status: there is no creators table, nothing to do.'; ELSE ALTER TABLE public.creators ADD COLUMN IF NOT EXISTS payments_status text; ALTER TABLE public.creators ADD COLUMN IF NOT EXISTS last_stripe_sync_at timestamptz; ALTER TABLE public.creators DROP CONSTRAINT IF EXISTS creators_payments_status_check; ALTER TABLE public.creators ADD CONSTRAINT creators_payments_status_check CHECK (payments_status IS NULL OR payments_status IN ('NOT_STARTED','INCOMPLETE','VERIFYING','ACTION_REQUIRED','BANK_REQUIRED','ACTIVE','RESTRICTED','PAYOUT_FAILED','SUSPENDED')); END IF; END $$;
CREATE OR REPLACE FUNCTION public.storelib_private_columns(p_table text) RETURNS text[] LANGUAGE sql IMMUTABLE AS $f$ SELECT CASE p_table WHEN 'creators' THEN ARRAY['stripe_account_id', 'stripe_customer_id', 'stripe_subscription_id', 'stripe_connected_at', 'stripe_onboarding_status', 'details_submitted', 'subscription_plan_id', 'subscription_status', 'pending_plan_id', 'paypal_merchant_id', 'payout_currency', 'payout_schedule', 'payout_threshold', 'instant_payouts_enabled', 'banned_reason', 'statement_descriptor', 'first_sale_email_sent', 'stripe_requirements', 'stripe_requirements_due_at', 'stripe_requirements_updated_at', 'payments_status', 'last_stripe_sync_at'] WHEN 'profiles' THEN ARRAY['email', 'role', 'spam_state', 'spam_score', 'personalized_recommendations', 'timezone', 'push_messages_enabled', 'push_preview_enabled', 'first_name', 'last_name', 'address_line1', 'address_line2', 'city', 'state', 'postal_code', 'country', 'phone', 'date_of_birth', 'tax_id'] ELSE ARRAY[]::text[] END $f$;
DO $do$ BEGIN IF to_regclass('public.creators') IS NOT NULL AND to_regprocedure('public.storelib_keep_server_columns()') IS NOT NULL THEN DROP TRIGGER IF EXISTS creators_keep_server_columns ON public.creators; CREATE TRIGGER creators_keep_server_columns BEFORE INSERT OR UPDATE ON public.creators FOR EACH ROW EXECUTE FUNCTION public.storelib_keep_server_columns('user_id', 'stripe_account_id', 'stripe_customer_id', 'stripe_subscription_id', 'stripe_connected_at', 'stripe_onboarding_status', 'details_submitted', 'charges_enabled', 'payouts_enabled', 'subscription_plan_id', 'subscription_status', 'pending_plan_id', 'paypal_merchant_id', 'banned_at', 'banned_reason', 'first_sale_email_sent', 'reviews_average', 'reviews_count', 'views', 'featured', 'stripe_requirements', 'stripe_requirements_due_at', 'stripe_requirements_updated_at', 'payments_status', 'last_stripe_sync_at'); END IF; END $do$;
DO $do$ BEGIN IF to_regprocedure('public.storelib_share_public_columns()') IS NOT NULL THEN PERFORM public.storelib_share_public_columns(); END IF; END $do$;
notify pgrst, 'reload schema';
